 <body>
   <a class="skip-link" href="#main-content">Skip to main content</a>

   <main id="main-content">
     <section class="support-card" aria-labelledby="support-title">
       <p class="eyebrow">Support</p>
       <h1 id="support-title">How can we reach you?</h1>
       <p class="intro">Share your contact details and our support team will get back to you.</p>

       <form id="support-form" novalidate>
         <p class="required-note"><span class="required-marker" aria-hidden="true">*</span> indicates a required field.</p>

         <div class="form-field">
           <label for="full-name">Full name <span class="required-marker" aria-hidden="true">*</span></label>
           <input
             id="full-name"
             name="full-name"
             type="text"
             autocomplete="name"
             required
             aria-describedby="full-name-error"
           >
           <p class="error-message" id="full-name-error">Error: Enter your full name.</p>
         </div>

         <div class="form-field">
           <label for="email">Email address <span class="required-marker" aria-hidden="true">*</span></label>
           <input
             id="email"
             name="email"
             type="email"
             autocomplete="email"
             required
             aria-describedby="email-error"
           >
           <p class="error-message" id="email-error">Error: Enter a valid email address, like name@example.com.</p>
         </div>

         <div class="form-field">
           <label for="phone">Phone number (optional)</label>
           <input
             id="phone"
             name="phone"
             type="tel"
             autocomplete="tel"
             inputmode="tel"
             aria-describedby="phone-help phone-error"
           >
           <p class="helper-text" id="phone-help">Use 10 digits, or include an optional country code, spaces, dashes, or parentheses.</p>
           <p class="error-message" id="phone-error">Error: Enter a valid phone number, such as (555) 123-4567 or +1 555 123 4567.</p>
         </div>

         <p class="form-status" id="form-status" aria-live="polite"></p>
         <button type="submit">Send support request</button>
       </form>
     </section>
   </main>

   <script>
     const form = document.querySelector("#support-form");
     const statusMessage = document.querySelector("#form-status");
     const fields = [
       {
         input: document.querySelector("#full-name"),
         error: document.querySelector("#full-name-error"),
         validate(value) {
           return value.trim().length > 0;
         }
       },
       {
         input: document.querySelector("#email"),
         error: document.querySelector("#email-error"),
         validate(value) {
           return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim());
         }
       },
       {
         input: document.querySelector("#phone"),
         error: document.querySelector("#phone-error"),
         validate(value) {
           const trimmedValue = value.trim();

           if (!trimmedValue) {
             return true;
           }

           return /^\+?[\d\s().-]{7,20}$/.test(trimmedValue) && trimmedValue.replace(/\D/g, "").length >= 7;
         }
       }
     ];

     function setFieldValidity(field, isValid) {
       field.input.setAttribute("aria-invalid", String(!isValid));
       field.error.classList.toggle("is-visible", !isValid);
     }

     function validateField(field) {
       const isValid = field.validate(field.input.value);
       setFieldValidity(field, isValid);
       return isValid;
     }

     fields.forEach((field) => {
       field.input.addEventListener("input", () => {
         validateField(field);
         statusMessage.textContent = "";
       });
     });

     form.addEventListener("submit", (event) => {
       event.preventDefault();

       const firstInvalidField = fields.find((field) => !validateField(field));

       if (firstInvalidField) {
         statusMessage.textContent = "";
         firstInvalidField.input.focus();
         return;
       }

       form.reset();
       fields.forEach((field) => setFieldValidity(field, true));
       statusMessage.textContent = "Your support request is ready to send.";
     });
   </script>
 </body>
 </html>

