<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Support Contact Form</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #0c111d;
      --panel: #141b2d;
      --panel-border: #2b3552;
      --text: #f5f7fb;
      --muted: #b6c0d4;
      --accent: #78a6ff;
