      border-radius: 999px;
      background: var(--focus);
      color: #111827;
      padding: 0.65rem 1rem;
      font-weight: 700;
      text-decoration: none;
    }

    .skip-link:focus {
      transform: translateY(0);
      outline: 3px solid #111827;
      outline-offset: 3px;
    }

    main {
      display: grid;
      min-height: 100vh;
      place-items: center;
      padding: 2rem 1rem;
    }

    .support-card {
      width: min(100%, 42rem);
      border: 1px solid var(--panel-border);
      border-radius: 1.5rem;
      background: rgba(20, 27, 45, 0.94);
      box-shadow: 0 1.5rem 4rem rgba(0, 0, 0, 0.35);
      padding: clamp(1.5rem, 5vw, 3rem);
    }

    .eyebrow {
      margin: 0 0 0.5rem;
      color: var(--accent-strong);
      font-size: 0.85rem;
      font-weight: 800;
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }

    h1 {
      margin: 0;
      font-size: clamp(2rem, 7vw, 3.25rem);
      line-height: 1.05;
    }

    .intro {
      margin: 1rem 0 2rem;
      color: var(--muted);
      font-size: 1.05rem;
    }

    .required-note {
      margin: 0 0 1.5rem;
      color: var(--muted);
      font-size: 0.95rem;
    }

    form {
      display: grid;
      gap: 1.25rem;
    }

    .form-field {
      display: grid;
      gap: 0.45rem;
    }

    label {
      color: var(--text);
      font-weight: 700;
    }

    .required-marker {
      color: var(--danger);
      font-weight: 900;
    }

    input {
      width: 100%;
      border: 1px solid #3d4967;
      border-radius: 0.9rem;
      background: var(--input-bg);
      color: var(--text);
      font: inherit;
      padding: 0.9rem 1rem;
      transition: border-color 160ms ease, box-shadow 160ms ease, background 160ms ease;
    }

    input::placeholder {
      color: #7f8aa3;
      opacity: 1;
    }

    input:hover {
      border-color: #586684;
    }

    input:focus,
    button:focus {
      outline: 3px solid var(--focus);
      outline-offset: 3px;
    }

    input[aria-invalid="true"] {
      border-color: var(--danger);
      background: linear-gradient(0deg, rgba(255, 154, 154, 0.08), rgba(255, 154, 154, 0.08)), var(--input-bg);
