    .error-message {
      display: none;
      border-left: 3px solid var(--danger);
      border-radius: 0.4rem;
      background: var(--danger-bg);
      color: var(--danger);
      padding: 0.5rem 0.75rem;
      font-weight: 650;
    }

    .error-message.is-visible {
      display: block;
    }

    .form-status {
      min-height: 1.5rem;
      margin: 0;
      color: var(--success);
      font-weight: 700;
