    .required-note {
      margin: 0 0 1.5rem;
      color: var(--muted);
      font-size: 0.95rem;
    }

    form {
      display: grid;
      gap: 1.25rem;
    }

    .form-field {
      display: grid;
      gap: 0.45rem;
    }

    label {
      color: var(--text);
      font-weight: 700;
    }

    .required-marker {
      color: var(--danger);
      font-weight: 900;
    }

    input {
      width: 100%;
      border: 1px solid #3d4967;
      border-radius: 0.9rem;
      background: var(--input-bg);
      color: var(--text);
      font: inherit;
      padding: 0.9rem 1rem;
      transition: border-color 160ms ease, box-shadow 160ms ease, background 160ms ease;
