294.     const fields = [
295.       {
296.         input: document.querySelector("#full-name"),
297.         error: document.querySelector("#full-name-error"),
298.         validate(value) {
299.           return value.trim().length > 0;
300.         }
301.       },
302.       {
303.         input: document.querySelector("#email"),
304.         error: document.querySelector("#email-error"),
305.         validate(value) {
306.           return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim());
307.         }
308.       },
309.       {
310.         input: document.querySelector("#phone"),
311.         error: document.querySelector("#phone-error"),
312.         validate(value) {
313.           const trimmedValue = value.trim();
314. 
315.           if (!trimmedValue) {
316.             return true;
317.           }
318. 
319.           return /^\+?[\d\s().-]{7,20}$/.test(trimmedValue) && trimmedValue.replace(/\D/g, "").length >= 7;
320.         }
321.       }
